// t18_squash -- generated by gen_t18_squash.py; do not edit by hand.
//
// A taken branch must squash the instruction after it. Needs two Role
// Contexts: with one, the fetch selection and the held entry's context
// always agree and the bug is invisible. Run with +allroles.
.org 0
start:
    s.rdspecial s60, role_id
    br.nz     s60, role1

// ---------------------------------------------------------------- role 0
// Present only to make the front end stall and the fetch selection
// alternate. What it computes does not matter.
role0:
    .li       s1, #32768
    .li       s2, #0
    .li       s3, #64
r0loop:
    s.ld.d    s4, [s1, #0]
    s.add     s2, s2, s4
    s.addi    s3, s3, #-1
    br.nz     s3, r0loop
    exit

// ---------------------------------------------------------------- role 1
role1:
    .li       s1, #32768
    .li       s2, #40
    .li       s4, #0
loop:
    s.ld.d    s3, [s1, #0]          // a load, to stall the front end
    s.addi    s4, s4, #1
    s.addi    s2, s2, #-1
    br.nz     s2, loop
    // Falling through here is correct once the count is exhausted. The
    // bug made it happen while the branch was TAKEN, so the counter check
    // below is what catches it: the loop body ran fewer times than the
    // branch said it should.
after:
    .assert_eq s4, #40, #1   // the loop ran exactly 40 times
    .assert_eq s2, #0, #2
    exit

.org 0x8000
flag:
    .dword 0

